class CommandBuilder:
    """
    Helps build CLI commands in a uniform way. For example,

    command = CommandBuilder(
        executable='/opt/oss/bin/nasdaclimx.sh',
        flags=['-objmgr', '-remove'],
        arguments=['MRBTS-100774'],
    )

    results in
    /opt/oss/bin/nasdaclimx.sh -objmgr -remove "MRBTS-100774"


    command = CommandBuilder(
        executable='fmCLI.sh',
        options={
            '-operation': 'bulkcancelalarms',
            '-dn': 'MRBTS-100774',
            '-include': True,
            '-includesubnetwork': False
        }
    )

    # results in
    fmCLI.sh -dn "MRBTS-100774" -includesubnetwork false -operation "bulkcancelalarms" -include true
    """

    def __init__(self, executable, flags=None, options=None, arguments=None):
        self.executable = executable
        self.flags = flags or []
        self.options = options or {}
        self.arguments = arguments or []

    def _convert_arguments(self):
        return ' '.join([f'"{e}"' for e in self.arguments])

    def _convert_flags(self):
        return ' '.join(self.flags)

    def _convert_options(self):
        converted_options = []
        for k, v in self.options.items():
            if v is not None:
                parsed_v = self._parse(v)
                converted_options.append(f'{k} {parsed_v}') if parsed_v else None
        return ' '.join(converted_options)

    @classmethod
    def _parse(cls, value):
        if isinstance(value, dict):
            return cls._parse_dict(value)
        elif isinstance(value, list):
            return cls._parse_list(value)
        elif isinstance(value, bool):
            return cls._parse_bool(value)
        else:
            return f'"{value}"'

    @staticmethod
    def _parse_dict(value):
        joined_dict_items = []
        for k, v in value.items():
            if isinstance(v, list):
                joined_dict_items.append(f"{k}={';'.join(v)}")
            elif v is not None:
                joined_dict_items.append(f"{k}={v}")

        return f'"{",".join(joined_dict_items)}"' if joined_dict_items else None

    @staticmethod
    def _parse_list(value):
        joined_list = ','.join(value)
        return f'"{joined_list}"' if joined_list else None

    @staticmethod
    def _parse_bool(value):
        return 'true' if value else 'false'

    @property
    def text(self):
        """
        Render command as string.

        :return: Command.
        :rtype: string
        """
        parameters = (self._convert_flags(), self._convert_options(), self._convert_arguments())
        return f'{self.executable} {" ".join(p for p in parameters if p)}'.replace('  ', ' ')
